@page "/courses"

<PageTitle>Browse Courses</PageTitle>

@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or instructor…" />
    </div>
    <div class="col-md-4">
        <select name="dept" class="form-select">
            <option value="">All Departments</option>
            @foreach (var d in Catalog.GetDepartments())
            {
                <option value="@d.Id" selected="@(Dept == d.Id)">@d.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var results = Catalog.SearchCourses(Search, Dept);
}

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var c in results)
            {
                <tr>
                    <td>@c.CourseCode</td>
                    <td>@c.Title</td>
                    <td>@c.DepartmentName</td>
                    <td>@c.Credits</td>
                    <td>@c.Schedule</td>
                    <td><a href="courses/@c.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">@results.Count course(s) found.</p>
}

@code {
    [SupplyParameterFromQuery(Name = "search")]
    public string? Search { get; set; }

    [SupplyParameterFromQuery(Name = "dept")]
    public int? Dept { get; set; }
}

@page "/courses/{Id:int}"

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The course you are looking for does not exist.</p>
    <a href="courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="departments/@course.DepartmentId">@course.DepartmentName</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <h1>@course.CourseCode — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Schedule &amp; Location</h4>
            <ul class="list-unstyled">
                <li><strong>Schedule:</strong> @course.Schedule</li>
                <li><strong>Location:</strong> @course.Location</li>
                <li><strong>Credits:</strong> @course.Credits</li>
            </ul>

            <h4 class="mt-4">Enrollment</h4>
            <div class="progress mb-2" style="height: 24px;">
                @{
                    var pct = course.MaxEnrollment > 0
                        ? (int)(100.0 * course.CurrentEnrollment / course.MaxEnrollment)
                        : 0;
                    var barClass = pct >= 100 ? "bg-danger" : pct >= 80 ? "bg-warning" : "bg-success";
                }
                <div class="progress-bar @barClass" role="progressbar"
                     style="width: @(pct)%;" aria-valuenow="@course.CurrentEnrollment"
                     aria-valuemin="0" aria-valuemax="@course.MaxEnrollment">
                    @course.CurrentEnrollment / @course.MaxEnrollment
                </div>
            </div>
            @if (course.CurrentEnrollment >= course.MaxEnrollment)
            {
                <span class="badge bg-danger">Full</span>
            }
            else
            {
                <a href="enroll?courseId=@course.Id" class="btn btn-success btn-sm">Request Enrollment</a>
            }
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Instructor</strong></div>
                <div class="card-body">
                    <h5 class="card-title">@course.Instructor.Name</h5>
                    <p class="card-text text-muted">@course.Instructor.Title</p>
                    <p class="card-text">@course.Instructor.Bio</p>
                    <ul class="list-unstyled mt-3">
                        <li><strong>Email:</strong> @course.Instructor.Email</li>
                        <li><strong>Office:</strong> @course.Instructor.OfficeLocation</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
    }
}

