@page "/enroll"

<PageTitle>Enrollment Request</PageTitle>

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive a confirmation email once your request is processed.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
           <strong>@selectedCourseTitle</strong> has been received.</p>
        <hr />
        <p class="mb-0">A confirmation will be sent to <strong>@Model.Email</strong>.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger mb-3" />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. CS123456" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email Address</label>
            <InputText id="email" @bind-Value="Model.Email" class="form-control" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">— Select a course —</option>
                @foreach (var c in Catalog.SearchCourses(null, null))
                {
                    <option value="@c.Id">@c.CourseCode — @c.Title (@c.DepartmentName)</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <div class="mb-3">
            <label for="comments" class="form-label">Comments (optional)</label>
            <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
            <ValidationMessage For="() => Model.Comments" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        if (PreselectedCourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null
            ? $"{course.CourseCode} — {course.Title}"
            : "Unknown course";

        Catalog.SubmitEnrollment(Model);
        submitted = true;
    }
}

